import React, { useState } from 'react';
import { AuthProvider, useAuth } from './AuthContext';
import Login from './Login';
import axios from 'axios';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid,
         Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';

const API = 'https://malawi-sales-backend.onrender.com';
const COLORS = ['#FF6B35', '#FFB800', '#2D6A4F', '#3E1F00', '#E63946', '#457B9D'];

function Dashboard() {
  const { user, logout, token } = useAuth();
  const [kpis, setKpis] = React.useState(null);
  const [regions, setRegions] = React.useState([]);
  const [categories, setCategories] = React.useState([]);
  const [sales, setSales] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [showForm, setShowForm] = React.useState(false);
  const [submitting, setSubmitting] = React.useState(false);
  const [successMsg, setSuccessMsg] = React.useState('');
  const [form, setForm] = React.useState({
    sale_date: '', product: '', category: '', region: '',
    customer: '', quantity: '', unit_price: '', unit_cost: '',
    salesperson: user?.name || '', payment: 'Cash'
  });

  React.useEffect(() => { fetchAll(); }, []);

  const fetchAll = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const [k, r, c, s] = await Promise.all([
        axios.get(`${API}/api/kpis`, { headers }),
        axios.get(`${API}/api/regions`, { headers }),
        axios.get(`${API}/api/categories`, { headers }),
        axios.get(`${API}/api/sales`, { headers }),
      ]);
      setKpis(k.data.data);
      setRegions(r.data.data);
      setCategories(c.data.data);
      setSales(s.data.data);
    } catch (err) {
      console.error('Error:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      await axios.post(`${API}/api/sales`, {
        ...form,
        quantity: parseInt(form.quantity),
        unit_price: parseFloat(form.unit_price),
        unit_cost: parseFloat(form.unit_cost),
      }, { headers: { Authorization: `Bearer ${token}` } });
      setSuccessMsg(`Sale submitted successfully!`);
      setForm({ sale_date: '', product: '', category: '',
                region: user?.region !== 'all' ? user.region : '',
                customer: '', quantity: '', unit_price: '', unit_cost: '',
                salesperson: user?.name || '', payment: 'Cash' });
      setShowForm(false);
      fetchAll();
      setTimeout(() => setSuccessMsg(''), 4000);
    } catch (err) {
      console.error('Submit error:', err);
    } finally {
      setSubmitting(false);
    }
  };

  const fmt = (n) => new Intl.NumberFormat('en-US', {
    minimumFractionDigits: 0, maximumFractionDigits: 0
  }).format(n || 0);

  const ROLE_BADGE = {
    admin: { bg: '#FF6B35', label: 'Admin' },
    salesperson: { bg: '#2D6A4F', label: 'Salesperson' },
    viewer: { bg: '#457B9D', label: 'Viewer' },
  };

  const badge = ROLE_BADGE[user?.role] || ROLE_BADGE.viewer;
  const canSubmit = user?.role !== 'viewer';

  return (
    <div style={{ fontFamily: 'Arial, sans-serif', background: '#FFF8F0', minHeight: '100vh' }}>

      {/* HEADER */}
      <div style={{ background: '#3E1F00', padding: '0 24px',
                    display: 'flex', alignItems: 'center',
                    justifyContent: 'space-between', height: 64 }}>
        <div>
          <div style={{ color: '#FFB800', fontSize: 22, fontWeight: 'bold' }}>SABIAS</div>
          <div style={{ color: '#FF6B35', fontSize: 11 }}>
            Sales & Business Intelligence Analytics System
          </div>
        </div>
        <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
          {/* User info */}
          <div style={{ textAlign: 'right' }}>
            <div style={{ color: 'white', fontSize: 13, fontWeight: 'bold' }}>
              {user?.name}
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, justifyContent: 'flex-end' }}>
              <span style={{ background: badge.bg, color: 'white', fontSize: 10,
                             padding: '2px 8px', borderRadius: 10, fontWeight: 'bold' }}>
                {badge.label}
              </span>
              {user?.region !== 'all' && (
                <span style={{ color: '#FFB800', fontSize: 11 }}>{user?.region}</span>
              )}
            </div>
          </div>
          <button onClick={fetchAll}
            style={{ background: 'transparent', border: '1px solid #FFB800',
                     color: '#FFB800', padding: '6px 14px', borderRadius: 6,
                     cursor: 'pointer', fontSize: 12 }}>
            Refresh
          </button>
          {canSubmit && (
            <button onClick={() => setShowForm(!showForm)}
              style={{ background: '#FF6B35', border: 'none', color: 'white',
                       padding: '8px 18px', borderRadius: 6, cursor: 'pointer',
                       fontWeight: 'bold', fontSize: 13 }}>
              + New Sale
            </button>
          )}
          <button onClick={logout}
            style={{ background: 'transparent', border: '1px solid #FF6B35',
                     color: '#FF6B35', padding: '6px 14px', borderRadius: 6,
                     cursor: 'pointer', fontSize: 12 }}>
            Logout
          </button>
        </div>
      </div>

      {/* SUCCESS MESSAGE */}
      {successMsg && (
        <div style={{ background: '#2D6A4F', color: 'white', padding: '12px 24px',
                      textAlign: 'center', fontWeight: 'bold' }}>
          ✓ {successMsg}
        </div>
      )}

      {/* VIEWER BANNER */}
      {user?.role === 'viewer' && (
        <div style={{ background: '#EBF5FB', borderBottom: '1px solid #AED6F1',
                      padding: '10px 24px', color: '#2980B9', fontSize: 13,
                      textAlign: 'center' }}>
          👁 You are in View-Only mode. Contact your admin to submit sales.
        </div>
      )}

      <div style={{ padding: 24 }}>

        {loading ? (
          <div style={{ textAlign: 'center', padding: 60, color: '#3E1F00', fontSize: 18 }}>
            Loading SABIAS data...
          </div>
        ) : (
          <>
            {/* KPI CARDS */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)',
                          gap: 16, marginBottom: 24 }}>
              {[
                { label: 'Total Revenue', value: `MK ${fmt(kpis?.total_revenue)}`, color: '#FF6B35' },
                { label: 'Total Profit', value: `MK ${fmt(kpis?.total_profit)}`, color: '#2D6A4F' },
                { label: 'Profit Margin', value: `${kpis?.total_profit && kpis?.total_revenue ?
                  ((kpis.total_profit / kpis.total_revenue) * 100).toFixed(1) : 0}%`, color: '#FFB800' },
                { label: 'Total Records', value: fmt(kpis?.total_records), color: '#3E1F00' },
              ].map((kpi, i) => (
                <div key={i} style={{ background: 'white', borderRadius: 12, padding: 20,
                  borderLeft: `4px solid ${kpi.color}`,
                  boxShadow: '0 2px 8px rgba(0,0,0,0.06)' }}>
                  <div style={{ color: '#888', fontSize: 12, marginBottom: 8 }}>{kpi.label}</div>
                  <div style={{ color: '#3E1F00', fontSize: 22, fontWeight: 'bold' }}>{kpi.value}</div>
                </div>
              ))}
            </div>

            {/* CHARTS */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr',
                          gap: 16, marginBottom: 24 }}>
              <div style={{ background: 'white', borderRadius: 12, padding: 20,
                            boxShadow: '0 2px 8px rgba(0,0,0,0.06)' }}>
                <div style={{ color: '#3E1F00', fontWeight: 'bold',
                              marginBottom: 16, fontSize: 14 }}>
                  Revenue by Region
                </div>
                <ResponsiveContainer width="100%" height={220}>
                  <BarChart data={regions}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0"/>
                    <XAxis dataKey="region" tick={{ fontSize: 11 }}/>
                    <YAxis tick={{ fontSize: 11 }}/>
                    <Tooltip formatter={(v) => [`MK ${fmt(v)}`, 'Revenue']}/>
                    <Bar dataKey="revenue" fill="#FF6B35" radius={[4,4,0,0]}/>
                  </BarChart>
                </ResponsiveContainer>
              </div>

              <div style={{ background: 'white', borderRadius: 12, padding: 20,
                            boxShadow: '0 2px 8px rgba(0,0,0,0.06)' }}>
                <div style={{ color: '#3E1F00', fontWeight: 'bold',
                              marginBottom: 16, fontSize: 14 }}>
                  Revenue by Category
                </div>
                <ResponsiveContainer width="100%" height={220}>
                  <PieChart>
                    <Pie data={categories} dataKey="revenue" nameKey="category"
                         cx="50%" cy="50%" outerRadius={80} innerRadius={40}>
                      {categories.map((_, i) => (
                        <Cell key={i} fill={COLORS[i % COLORS.length]}/>
                      ))}
                    </Pie>
                    <Tooltip formatter={(v) => [`MK ${fmt(v)}`, 'Revenue']}/>
                    <Legend/>
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>

            {/* NEW SALE FORM */}
            {showForm && canSubmit && (
              <div style={{ background: 'white', borderRadius: 12, padding: 24,
                            boxShadow: '0 2px 8px rgba(0,0,0,0.06)', marginBottom: 24 }}>
                <div style={{ color: '#3E1F00', fontWeight: 'bold',
                              fontSize: 16, marginBottom: 20 }}>
                  Submit New Sale
                </div>
                <form onSubmit={handleSubmit}>
                  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 12 }}>
                    {[
                      { label: 'Sale Date', key: 'sale_date', type: 'date' },
                      { label: 'Product Name', key: 'product', type: 'text' },
                      { label: 'Category', key: 'category', type: 'text' },
                      { label: 'Region', key: 'region', type: 'text' },
                      { label: 'Customer', key: 'customer', type: 'text' },
                      { label: 'Quantity', key: 'quantity', type: 'number' },
                      { label: 'Unit Price (MWK)', key: 'unit_price', type: 'number' },
                      { label: 'Unit Cost (MWK)', key: 'unit_cost', type: 'number' },
                      { label: 'Salesperson', key: 'salesperson', type: 'text' },
                    ].map(({ label, key, type }) => (
                      <div key={key}>
                        <label style={{ fontSize: 11, color: '#888',
                                        display: 'block', marginBottom: 4 }}>
                          {label}
                        </label>
                        <input type={type} required value={form[key]}
                          onChange={(e) => setForm({ ...form, [key]: e.target.value })}
                          style={{ width: '100%', padding: '8px 10px', borderRadius: 6,
                            border: '1px solid #FFB800', fontSize: 13,
                            boxSizing: 'border-box' }}/>
                      </div>
                    ))}
                    <div>
                      <label style={{ fontSize: 11, color: '#888',
                                      display: 'block', marginBottom: 4 }}>
                        Payment Method
                      </label>
                      <select value={form.payment}
                        onChange={(e) => setForm({ ...form, payment: e.target.value })}
                        style={{ width: '100%', padding: '8px 10px', borderRadius: 6,
                          border: '1px solid #FFB800', fontSize: 13,
                          boxSizing: 'border-box' }}>
                        <option>Cash</option>
                        <option>Mobile Money</option>
                        <option>Credit</option>
                        <option>Bank Transfer</option>
                      </select>
                    </div>
                  </div>
                  <div style={{ marginTop: 20, display: 'flex', gap: 12 }}>
                    <button type="submit" disabled={submitting}
                      style={{ background: '#FF6B35', border: 'none', color: 'white',
                        padding: '10px 28px', borderRadius: 6, cursor: 'pointer',
                        fontWeight: 'bold', fontSize: 14 }}>
                      {submitting ? 'Submitting...' : 'Submit Sale'}
                    </button>
                    <button type="button" onClick={() => setShowForm(false)}
                      style={{ background: '#3E1F00', border: 'none', color: '#FFB800',
                        padding: '10px 28px', borderRadius: 6, cursor: 'pointer',
                        fontWeight: 'bold', fontSize: 14 }}>
                      Cancel
                    </button>
                  </div>
                </form>
              </div>
            )}

            {/* SALES TABLE */}
            <div style={{ background: 'white', borderRadius: 12, padding: 20,
                          boxShadow: '0 2px 8px rgba(0,0,0,0.06)' }}>
              <div style={{ color: '#3E1F00', fontWeight: 'bold',
                            fontSize: 14, marginBottom: 16 }}>
                Sales Records
                {user?.role === 'salesperson' && (
                  <span style={{ color: '#888', fontSize: 12, fontWeight: 'normal',
                                 marginLeft: 8 }}>
                    (Showing all records)
                  </span>
                )}
              </div>
              <div style={{ overflowX: 'auto' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
                  <thead>
                    <tr style={{ background: '#3E1F00' }}>
                      {['Date','Product','Category','Region','Customer',
                        'Qty','Unit Price','Revenue','Profit','Margin %','Salesperson'].map(h => (
                        <th key={h} style={{ padding: '10px 12px', color: '#FFB800',
                          textAlign: 'left', fontWeight: 'bold', whiteSpace: 'nowrap' }}>
                          {h}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {sales.slice(0, 25).map((s, i) => (
                      <tr key={s.id} style={{
                        background: i % 2 === 0 ? '#FFF8F0' : 'white',
                        borderBottom: '1px solid #FFE8D0' }}>
                        <td style={{ padding: '9px 12px' }}>{s.sale_date?.split('T')[0]}</td>
                        <td style={{ padding: '9px 12px', fontWeight: '500',
                                     color: '#3E1F00' }}>{s.product}</td>
                        <td style={{ padding: '9px 12px' }}>{s.category}</td>
                        <td style={{ padding: '9px 12px' }}>{s.region}</td>
                        <td style={{ padding: '9px 12px' }}>{s.customer}</td>
                        <td style={{ padding: '9px 12px', textAlign: 'right' }}>
                          {fmt(s.quantity)}
                        </td>
                        <td style={{ padding: '9px 12px', textAlign: 'right' }}>
                          MK {fmt(s.unit_price)}
                        </td>
                        <td style={{ padding: '9px 12px', textAlign: 'right',
                                     color: '#2D6A4F', fontWeight: '500' }}>
                          MK {fmt(s.revenue)}
                        </td>
                        <td style={{ padding: '9px 12px', textAlign: 'right',
                                     color: '#FF6B35', fontWeight: '500' }}>
                          MK {fmt(s.profit)}
                        </td>
                        <td style={{ padding: '9px 12px', textAlign: 'right' }}>
                          {s.margin ? (parseFloat(s.margin) * 100).toFixed(1) : 0}%
                        </td>
                        <td style={{ padding: '9px 12px' }}>{s.salesperson}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </>
        )}
      </div>

      {/* FOOTER */}
      <div style={{ background: '#3E1F00', color: '#FFB800', textAlign: 'center',
                    padding: 14, fontSize: 12, marginTop: 40 }}>
        SABIAS © 2026 · Sales & Business Intelligence Analytics System ·
        Powered by React + Node.js + PostgreSQL
      </div>
    </div>
  );
}

function AppContent() {
  const { user, loading } = useAuth();
  const [loggedIn, setLoggedIn] = useState(false);

  if (loading) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center',
                    justifyContent: 'center', background: '#FFF8F0',
                    fontFamily: 'Arial' }}>
        <div style={{ color: '#3E1F00', fontSize: 18 }}>Loading SABIAS...</div>
      </div>
    );
  }

  if (!user && !loggedIn) {
    return <Login onLogin={() => setLoggedIn(true)}/>;
  }

  return <Dashboard/>;
}

export default function App() {
  return (
    <AuthProvider>
      <AppContent/>
    </AuthProvider>
  );
}
